function fnUpdateNavigation(index, activeIndex, lines) {

    if (index > activeIndex) {


        // Highlight all lines between activeIndex and the new index
        for (let i = activeIndex; i < index; i++) {
            if (i === index - 1 && index != activeIndex + 1) {
                // Add delay for the last line
                setTimeout(() => {
                    lines[i].classList.add('highlight-down');
                }, 600); // Adjust delay (in ms) as needed
            } else {
                lines[i].classList.add('highlight-down');
            }
        }
    }

    if (index < activeIndex) {

        // Highlight all lines between activeIndex and the new index
        for (let i = activeIndex - 1; i >= index; i--) {
            if (i === index && index != activeIndex - 1) {
                // Add delay for the last line (first in this upward flow)
                setTimeout(() => {
                    lines[i].classList.add('highlight-up');
                }, 600); // Adjust delay (in ms) as needed
            } else {
                lines[i].classList.add('highlight-up');
            }
        }
    }
}

