const playerCollider = new THREE.Sphere(new THREE.Vector3(0, 0, 0),);
playerCollider.center.set(endPosition.x, getHeight(endPosition.x, endPosition.y), endPosition.z);
const intersects = [];

function fnUpdateControls(deltaTime) {
    // Create a new Vector3 for the player's potential next position
    const newPosition = playerCollider.center.clone();


    // Get the direction the player is facing
    const direction = new THREE.Vector3();
    controls.getDirection(direction);

    // Calculate the right vector relative to the player's look direction
    const right = new THREE.Vector3();
    right.crossVectors(direction, controls.getObject().up);

    // Apply velocity decay
    velocity.x -= velocity.x * 10.0 * deltaTime;
    velocity.z -= velocity.z * 10.0 * deltaTime;

    // Update velocity based on input
    if (moveForward) velocity.z -= SPEED * deltaTime;
    if (moveBackward) velocity.z += SPEED * deltaTime;
    if (moveLeft) velocity.x += SPEED * deltaTime;
    if (moveRight) velocity.x -= SPEED * deltaTime;

    // Calculate movement direction and update the new position
    newPosition.addScaledVector(direction, -velocity.z * deltaTime);
    newPosition.addScaledVector(right, -velocity.x * deltaTime);



    // --- COLLISION CHECK START ---
    const playerRadius = 6.0;
    const playerSphere = new THREE.Sphere(newPosition, playerRadius);

    const closestPoint = new THREE.Vector3();

    modelRegistry.forEach((data, id) => {
        //is object in frustrum and within distance
        //if (!Utils.fnIsInFrustum(data.mesh, camera) || !Utils.fnIsWithinDistance(data.position, newPosition, data.collisionRadius)) return;
        if (!Utils.fnIsWithinDistance(data.position, newPosition, data.collisionRadius)) return;

        if (data.bvh) {
            if (data.name.includes('figure')) {
                fnToggleFigureAnimation(stoneFigureParams, data.name)
            }
            data.bvh.shapecast({
                intersectsBounds: box => box.intersectsSphere(playerSphere),
                intersectsTriangle: tri => {

                    tri.closestPointToPoint(newPosition, closestPoint);
                    const distance = newPosition.distanceTo(closestPoint);

                    if (distance < playerRadius) {
                        const penetrationDepth = playerRadius - distance;
                        const displacement = newPosition.clone().sub(closestPoint).normalize().multiplyScalar(penetrationDepth);
                        newPosition.add(displacement);  // Push player out of collision

                    }
                }
            });
        }
    });


    if (intersects.length > 0) {
        for (const { tri, closestPoint, distance } of intersects) {
            // Get collision normal
            const collisionNormal = tri.getNormal(new THREE.Vector3());

            // Push the player out along the collision normal
            const penetrationDepth = playerRadius - distance;
            newPosition.addScaledVector(collisionNormal, penetrationDepth);

            // Slide along the collision plane
            const velocityDot = velocity.dot(collisionNormal);
            const slideVector = velocity.clone().sub(collisionNormal.multiplyScalar(velocityDot));
            velocity.copy(slideVector);
        }
    }
    // --- COLLISION CHECK END ---

    // Apply the new position
    playerCollider.center.copy(newPosition);
    controls.getObject().position.copy(playerCollider.center);

    // Sample Y-value from the height data array to ensure the player stays on the terrain
    const height = getHeight(playerCollider.center.x, playerCollider.center.z);
    playerCollider.center.y = height + PERSON_HEIGHT;
    controls.getObject().position.y = playerCollider.center.y;
}







